export const getGetMatchScoreUrl = (id: number,
    params: GetMatchScoreParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/internships/${id}/match?${stringifiedParams}` : `/api/internships/${id}/match`
}

